CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS consultants (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, client TEXT NOT NULL, position TEXT NOT NULL, coef REAL NOT NULL, tariff REAL NOT NULL, start_date TEXT NOT NULL, end_date TEXT, fees REAL, coef_percentage REAL, coef_margin REAL, manager_bonus REAL, simulation_inputs TEXT, profitability_status TEXT DEFAULT 'INSUFFICIENT_DATA', gross_monthly_salary REAL, net_monthly_salary REAL, net_annual_salary REAL, monthly_ss REAL, monthly_irpf REAL, irpf_rate REAL, ss_rate REAL, coef_projection TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS cost_concepts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('monthly','yearly','onetime')), default_value REAL NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE VIEW IF NOT EXISTS v_client_financials AS SELECT client, COUNT(*) as consultant_count, COALESCE(SUM(fees),0) as total_fees, COALESCE(SUM(coef_margin),0) as total_margin, COALESCE(SUM(manager_bonus),0) as total_bonus, COALESCE(AVG(julianday('now')-julianday(start_date)),0) as avg_tenure, COALESCE(MAX(julianday('now')-julianday(start_date)),0) as max_tenure FROM consultants WHERE end_date IS NULL OR end_date > datetime('now') GROUP BY client;
CREATE VIEW IF NOT EXISTS v_position_profitability AS SELECT position, COUNT(*) as consultant_count, COALESCE(SUM(fees),0) as total_fees, COALESCE(AVG(coef_percentage),0) as avg_coef, COALESCE(SUM(coef_margin),0) as total_margin FROM consultants WHERE end_date IS NULL OR end_date > datetime('now') GROUP BY position;
CREATE TABLE IF NOT EXISTS tenure_bonuses (id INTEGER PRIMARY KEY AUTOINCREMENT, consultant_id INTEGER NOT NULL, amount REAL NOT NULL, paid_month TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(consultant_id, paid_month));
CREATE TABLE IF NOT EXISTS quarterly_bonuses (id INTEGER PRIMARY KEY AUTOINCREMENT, year INTEGER NOT NULL, quarter INTEGER NOT NULL, amount REAL NOT NULL, net_hires INTEGER NOT NULL DEFAULT 0, target_hires INTEGER NOT NULL DEFAULT 0, earned INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(year, quarter));
CREATE TABLE IF NOT EXISTS bonus_breakdown_cache (id INTEGER PRIMARY KEY AUTOINCREMENT, year INTEGER NOT NULL, month_label TEXT NOT NULL, manager_bonus REAL NOT NULL DEFAULT 0, tenure_count INTEGER NOT NULL DEFAULT 0, tenure_amount REAL NOT NULL DEFAULT 0, projected_tenure_count INTEGER NOT NULL DEFAULT 0, projected_tenure_amount REAL NOT NULL DEFAULT 0, quarterly_count INTEGER NOT NULL DEFAULT 0, quarterly_amount REAL NOT NULL DEFAULT 0, total_bonus REAL NOT NULL DEFAULT 0, UNIQUE(year, month_label));
CREATE TABLE IF NOT EXISTS simulations (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, inputs TEXT, results TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_consultants_client ON consultants(client);
CREATE INDEX IF NOT EXISTS idx_consultants_start_date ON consultants(start_date);
CREATE INDEX IF NOT EXISTS idx_consultants_end_date ON consultants(end_date);
CREATE UNIQUE INDEX IF NOT EXISTS idx_cost_concepts_name ON cost_concepts(name);
